// План specs/job-dates.md 1.3–1.4 (кейсы .qa/tests/job-dates/JDT-04, JDT-05). Admin, компания «test», десктоп, браузер в America/New_York
// («сегодня» — по времени США, как у пользователя). Колонка Scheduled списка Jobs.
//  1.3 @prod-safe — каждая строка всех вкладок статусов: метка соответствует разнице календарных дней (EN и HE).
//  1.4 @writes    — создаёт 4 работы «QA-AUTO rel #6605fa …» (завтра, +3, вчера, −5; QA-quota client, без техников),
//                   проверяет точные метки EN/HE и в finally переводит их в Cancelled. send-sms перехватывается.
import { test, expect } from '@playwright/test';
import {
  ADMIN_STATE, Lang, T, US_TZ, addDays, allScheduledCells, blockSmsSending, cancelJobs, columnIndex, createQaJob, dayDiff,
  expectNoSmsSent, expectedRelative, jobRow, openJobsList, parseScheduled, restoreCompany, todayUs, useLang,
} from './job-dates-helpers';

test.use({ storageState: ADMIN_STATE, timezoneId: US_TZ });

test.describe('Jobs list: relative date labels in Scheduled (#6605fa)', () => {
  for (const lang of ['en', 'he'] as Lang[]) {
    test(`Jobs list (${lang.toUpperCase()}): every Scheduled label matches the calendar-day difference; Today only for today #6605fa @desktop @prod-safe`, async ({ page }) => {
      test.setTimeout(180_000);
      await useLang(page, lang);
      const smsHits = await blockSmsSending(page);
      try {
        await openJobsList(page);
        const tabs = page.locator('main').getByRole('tab');
        const tabCount = await tabs.count();
        expect(tabCount, 'вкладки статусов').toBeGreaterThan(1);
        const today = todayUs();
        const problems: string[] = [];
        let checked = 0;
        for (let t = 0; t < tabCount; t++) {
          const tab = tabs.nth(t);
          await tab.click();
          await expect(tab).toHaveAttribute('aria-selected', 'true');
          if (!(await page.locator('main tbody tr').filter({ hasText: /JOB-\s*\d{4}/ }).count())) continue;
          for (const { job, text } of await allScheduledCells(page, lang)) {
            const cell = parseScheduled(text, lang);
            if (cell.kind === 'none') continue;
            if (cell.kind === 'other') { problems.push(`${job}: не разобрано «${cell.text}»`); continue; }
            const diff = dayDiff(cell.date, today);
            const want = expectedRelative(diff, lang);
            checked++;
            // Источник: «מה רצוי» + комментарий программиста — Today/מחר/בעוד N ימים/אתמול/לפני N ימים, месяцы от 30 дней.
            if (!want.test(cell.label)) problems.push(`${job}: «${text}» — разница ${diff} дн., ждём ${want}`);
          }
        }
        expect(checked, 'в списке есть работы с датой').toBeGreaterThan(0);
        expect(problems, 'метки Scheduled').toEqual([]);
      } finally {
        await restoreCompany(page);
      }
      expectNoSmsSent(smsHits);
    });
  }

  test('Jobs list (EN + HE): jobs for tomorrow, in 3 days, yesterday and 5 days ago get Tomorrow/In 3 days/Yesterday/5 days ago and מחר/בעוד 3 ימים/אתמול/לפני 5 ימים #6605fa @desktop @writes', async ({ page }) => {
    test.setTimeout(420_000);
    await useLang(page, 'en');
    const smsHits = await blockSmsSending(page);
    const stamp = Date.now().toString(36);
    const cases = [
      { offset: 1, en: /^Tomorrow$/, he: /^מחר$/ },
      { offset: 3, en: /^In 3 days$/, he: /^בעוד 3 ימים$/ },
      { offset: -1, en: /^Yesterday$/, he: /^אתמול$/ },
      { offset: -5, en: /^5 days ago$/, he: /^לפני 5 ימים$/ },
    ];
    const jobs: { code: string; url: string; offset: number; en: RegExp; he: RegExp }[] = [];
    try {
      for (const c of cases) {
        const job = await createQaJob(page, `QA-AUTO rel #6605fa ${c.offset >= 0 ? '+' : ''}${c.offset} ${stamp}`, c.offset);
        jobs.push({ ...job, ...c });
      }
      for (const lang of ['en', 'he'] as Lang[]) {
        await useLang(page, lang);
        await openJobsList(page);
        const idx = await columnIndex(page, T[lang].scheduled);
        for (const j of jobs) {
          const row = jobRow(page, j.code);
          await expect(row, `${j.code} во вкладке по умолчанию (Submitted)`).toBeVisible();
          const text = (await row.locator('td, [role="cell"]').nth(idx).innerText()).trim();
          const cell = parseScheduled(text, lang);
          expect(cell.kind, `${j.code}: «${text}»`).toBe('date');
          if (cell.kind !== 'date') continue;
          expect(cell.date, `${j.code}: дата`).toEqual(addDays(todayUs(), j.offset));
          // Источник: «מה רצוי» — מחר = Tomorrow/מחר; בעתיד — in N days/בעוד N ימים; בעבר — לפני N ימים, אתמול.
          expect(cell.label, `${j.code} (${lang}) смещение ${j.offset}`).toMatch(j[lang]);
        }
      }
    } finally {
      await cancelJobs(page, jobs.map((j) => j.url));
      await restoreCompany(page);
    }
    expectNoSmsSent(smsHits);
  });
});
